{
  "title": "Discussion on tax filing, domain purchase, and low‑profit app ideas",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Problems with tax declarations and inspector issues",
      "claims": [
        {
          "text": "The author paid 500 UAH to aunt Sveta to fix large tax‑declaration errors caused by mis‑labelled columns.",
          "evidence": [1]
        },
        {
          "text": "The inspector ignored the author's declarations for 1.5 years and only started demanding re‑verification after being reprimanded in Kyiv.",
          "evidence": [1]
        },
        {
          "text": "With Sveta's help the author managed to re‑declare correctly and paid about 1 000 UAH instead of larger fines.",
          "evidence": [1]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Conversation about buying a domain",
      "claims": [
        {
          "text": "User P2 claimed they haven't bought a domain.",
          "evidence": [2]
        },
        {
          "text": "P1 sarcastically suggested someone should buy a calculator first, then there will be money for a domain.",
          "evidence": [4]
        },
        {
          "text": "P4 expressed doubt that a domain would be purchased, calling it a “silly thing”.",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Assessment of a low‑profit web/app project",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS apps.",
          "evidence": [11]
        },
        {
          "text": "SEO for the web project is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from social media or contextual ads, and app stores promote new apps more effectively.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds, deterring buyers.",
          "evidence": [11]
        },
        {
          "text": "Conversion rate is assumed to be zero; the product doesn’t simplify tasks nor integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "A successful similar project emphasized very fast delivery (under a week) and a cross‑platform stack (Flutter).",
          "evidence": [12]
        },
        {
          "text": "P1 doubts the project's marketability, betting that nobody will buy it within months.",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "technical-limitations",
      "title": "Calculator and currency handling limitations",
      "claims": [
        {
          "text": "The calculator works only with Ukrainian‑currency (UAH) FOPs; the author had to convert all transactions using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "password-source-code",
      "title": "Speculation about source code and password retrieval",
      "claims": [
        {
          "text": "P4 jokes that they did not pay 299 UAH for the product and implies the password is stored in local storage as a 100 % discount promo code.",
          "evidence": [20, 22]
        },
        {
          "text": "P4 mentions the password is included in the bundle.",
          "evidence": [23]
        },
        {
          "text": "P5 calls the approach “pirate” and suggests writing to the author.",
          "evidence": [24, 25]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app without problems.",
          "evidence": [28]
        }
      ]
    },
    {
      "id": "project-perception",
      "title": "Perception of the project as a free “vibe‑code” experiment",
      "claims": [
        {
          "text": "P4 describes the project as a “free vibe‑code” experiment done out of boredom with little sense, where only technically curious people will inspect the password.",
          "evidence": [30, 31, 32]
        },
        {
          "text": "P5 confirms the project's nature as “vibe‑code”.",
          "evidence": [33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
